script:
SandboxLog('factory polygon - unregistered only');
ProbePoly := PCBServer.PCBObjectFactory(ePolyObject, eNoDimension, eCreate_Default);
ProbePoly.Name := 'MCP_UNREGISTERED_PROBE';
ProbePoly.Layer := eTopLayer;
ProbePoly.PolygonType := eSignalLayerPolygon;
ProbePoly.PolyHatchStyle := ePolySolid;
ProbePoly.PourOver := ePolygonPourOver_SameNet;
ProbePoly.RemoveDead := True;
ProbePoly.RemoveIslandsByArea := False;
ProbePoly.RemoveNarrowNecks := True;
ProbePoly.NeckWidthThreshold := MMsToCoord(0.15);
ProbePoly.ArcApproximation := MMsToCoord(0.01);
ProbePoly.PointCount := 3;
for I1 := 0 to 2 do begin
 ProbeSeg := TPolySegment;
 ProbeSeg.Kind := ePolySegmentLine;
 ProbeSeg.vx := MMsToCoord(I1);
 ProbeSeg.vy := MMsToCoord(I1 mod 2);
 ProbePoly.Segments[I1] := ProbeSeg;
end;
SandboxLog('polygon properties assigned: ' + ProbePoly.Name);
ProbeSeg := ProbePoly.Segments[2];
SandboxLog('polygon shape count=' + IntToStr(ProbePoly.PointCount) + ' vx=' + IntToStr(ProbeSeg.vx));
SandboxLog('factory polygon cutout - unregistered only');
ProbeRegion := PCBServer.PCBObjectFactory(eRegionObject, eNoDimension, eCreate_Default);
ProbeRegion.Name := 'MCP_UNREGISTERED_CUTOUT_PROBE';
ProbeRegion.Kind := eRegionKind_Cutout;
ProbeRegion.Layer := eBottomLayer;
ProbeRegion.IsKeepout := False;
ProbeRegion.ShapeSegmentCount := 3;
for I1 := 0 to 2 do begin
 ProbeSeg := TPolySegment;
 ProbeSeg.Kind := ePolySegmentLine;
 ProbeSeg.vx := MMsToCoord(I1);
 ProbeSeg.vy := MMsToCoord(I1 mod 2);
 ProbeRegion.ShapeSegments[I1] := ProbeSeg;
end;
ProbeRegion.UpdateContourFromShape(True);
ProbeContour := ProbeRegion.MainContour;
SandboxLog('cutout contour count=' + IntToStr(ProbeContour.Count));
ProbePoly := nil;
ProbeRegion := nil;
ResultText := '{"success":true,"registered_objects":0,"board_modified":false,"properties_supported":true}';
